//! `GET __path__`: the `__template__` template in the site's layout
//! (generated by `engine generate handler __name__`).

use axum::extract::State;
use engine_cli::app::{Context, HandlerResult, Page};
use engine_cli::minijinja::context;

/// `GET __path__`. Read what the page shows here (`cx.db()`,
/// `cx.query(...)`, `cx.session(&headers)`) and pass it to the template.
pub async fn handle(State(cx): State<Context>) -> HandlerResult<Page> {
    let page = cx
        .render(
            "__template__",
            context! { page => context! { title => "__Label__" } },
        )
        .await?;
    Ok(page)
}
